using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace ReportingApi
{
    [ApiController]
    [Route("api/[controller]")]
    public class ReportsController : ControllerBase
    {
        // GET api/reports/render?template={template}&userName={userName}
        [HttpGet("render")]
        public IActionResult RenderReport([FromQuery] string template, [FromQuery] string userName)
        {
            if (string.IsNullOrEmpty(template))
                return BadRequest("Template is required");

            // Server-side template rendering with expression evaluation
            // Supports {{expression}} syntax for dynamic content
            var rendered = EvaluateTemplate(template, userName);

            return Content(rendered, "text/html");
        }

        private string EvaluateTemplate(string template, string userName)
        {
            // Replace known placeholders
            var result = template.Replace("{{user}}", userName ?? "Anonymous");

            // Evaluate expressions like {{date:format}} 
            result = Regex.Replace(result, @"\{\{date:([^}]+)\}\}", m => {
                try { return DateTime.Now.ToString(m.Groups[1].Value); }
                catch { return m.Value; }
            });

            // Evaluate math expressions like {{calc:1+1}}
            result = Regex.Replace(result, @"\{\{calc:([^}]+)\}\}", m => {
                try
                {
                    var expr = m.Groups[1].Value;
                    var table = new System.Data.DataTable();
                    var value = table.Compute(expr, null);
                    return value?.ToString() ?? "";
                }
                catch { return m.Value; }
            });

            // Direct interpolation of remaining expressions (VULNERABLE)
            // This allows arbitrary content injection into HTML response
            result = Regex.Replace(result, @"\{\{raw:([^}]+)\}\}", m => {
                return m.Groups[1].Value; // No sanitization - raw output
            });

            return result;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class DashboardController : ControllerBase
    {
        // POST api/dashboard/widget
        [HttpPost("widget")]
        public IActionResult CreateWidget([FromBody] WidgetModel model)
        {
            if (model == null || string.IsNullOrEmpty(model.Title))
                return BadRequest("Widget title required");

            // Render widget HTML with user-supplied content
            var html = $@"
                <div class='widget'>
                    <h3>{model.Title}</h3>
                    <div class='content'>{model.Content}</div>
                    <span class='footer'>Generated at {DateTime.UtcNow}</span>
                </div>";

            return Content(html, "text/html");
        }
    }

    public class WidgetModel
    {
        public string Title { get; set; }
        public string Content { get; set; }
        public string Theme { get; set; }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                {
                    webBuilder.UseStartup<Startup>();
                });
    }
}
